INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106707, 'spa', 'así, de este modo', 'Adverbio primario de modo: ''así, de este modo, de igual manera''. Describe la conformidad entre mandato y ejecución, y domina el relato de la Creación: ''y fue así'' (Gn 1:7, 9, 11, 15, 24). Responde a la pregunta ''¿cómo?'' señalando hacia una descripción o modelo previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106708, 'spa', 'por tanto (inferencia causal)', 'Conjunción causal-inferencial: ''por tanto, por esta razón, a causa de esto'', típicamente en el compuesto לָכֵן. Extrae conclusiones lógicas de premisas previas y constituye la columna vertebral de los oráculos proféticos de juicio: ''por tanto, así dice el Señor'' (Nm 20:12; Is 5:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106713, 'spa', 'así (discurso general)', 'Partícula discursiva transicional que combina matices de modo y causa, haciendo avanzar la narrativa o el argumento sin significar estrictamente ''de este modo'' ni ''por tanto''. Aparece en fórmulas etiológicas como ''por eso se llama...'' (Gn 10:9; 11:9; 16:14), donde funciona como puente entre ambas lecturas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106716, 'spa', 'esto, eso (anafórico)', 'Uso demostrativo anafórico que señala hacia una situación previamente mencionada: ''esta cosa, tal asunto''. En Jos 7:26 y 8:34 כֵּן se refiere a ''todo lo que estaba escrito'', y en Sal 42:6 el salmista recuerda ''esto'' acerca de su alma. Lectura demostrativa, no de modo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106727, 'spa', 'entonces (temporal)', 'Adverbio temporal: ''entonces, en aquel momento''. Atestiguado en Neh 2:16, donde Nehemías informa que ''los oficiales aún no sabían adónde había ido ni qué había hecho; hasta entonces (עַד כֵּן) no había dicho nada''. Fuerza temporal distinta de la modal o causal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106728, 'spa', 'ciertamente (afirmativo)', 'Partícula afirmativa: ''ciertamente, sí, en efecto'', usada para confirmar o asentir. En Esd 10:12 la asamblea responde ''¡כֵּן! — así es, conforme has dicho''. Funciona pragmáticamente como asentimiento más que como descripción, equivalente al español ''así es'' en registro confirmatorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106732, 'spa', 'tanto, en tal grado', 'Adverbio de grado: ''tanto, en tal medida, suficiente'', cuantificando en lugar de describir modo. Atestiguado en Jue 21:14 donde las mujeres de Jabés de Galaad ''no bastaron'' (לֹא מָצְאוּ כֵן). Este sentido cuantitativo se distingue de los sentidos de modo o causa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106734, 'spa', 'Y así, de este modo', 'Adverbio discursivo que significa «así, de esta manera», que típicamente introduce discurso referido o resume el contenido de un documento. La fórmula «y así dijo» aparece en Daniel 2:24–25, 4:14, 6:7 y 7:5, 23, mientras que Esdras 5:3 y 6:2 la extienden a indagaciones oficiales y registros escritos. Señala deícticamente hacia lo que sigue o hacia lo que acaba de mencionarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106736, 'spa', 'Base, soporte o pedestal físico', 'Base, soporte o pedestal físico. El sentido arquitectónico concreto: una base o pedestal que sostiene físicamente otro objeto. Casi todas las apariciones se refieren al soporte de bronce del lavacro (kiyor) en el tabernáculo (Éx 30:18, 38:8, Lv 8:11). Isaías 33:23 lo usa para el soporte del mástil de un barco. El árabe qaa''ida (''base/pedestal'') es un equivalente cercano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106737, 'spa', 'Lugar, posición u oficio', 'Lugar, posición u oficio. El sentido abstracto posicional: el puesto, la posición o el cargo asignado a alguien. El copero es restaurado ''a su puesto'' (Gn 40:13), y José relata su propia restauración ''a mi lugar'' (Gn 41:13). Daniel lo emplea para la sucesión real, donde cada gobernante se levanta ''en su lugar'' o es reemplazado por otro que se establece ''en su posición'' (Dn 11:7, 20, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106742, 'spa', 'Asimismo, de igual manera (uso adverbial)', 'Asimismo, de igual manera (uso adverbial). Un uso adverbial poco frecuente que significa ''asimismo'', ''así'' o ''de la misma manera'', donde el sentido nominal de ''fundamento'' se ha extendido para significar ''sobre esa base, por tanto''. Aparece en 1 Reyes 7:29 en la descripción de la obra ornamental de los soportes. La trayectoria semántica de ''fundamento'' a ''por consiguiente'' tiene paralelo en el árabe kadhalika (''asimismo/así'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106744, 'spa', 'Los mosquitos/piojos', 'Mosquitos o piojos, los insectos que enjambraron durante la tercera plaga de Egipto. En Éx 8:16-18, Aarón golpea el polvo y este se convierte en כִּנִּים por todo Egipto; el Sal 105:31 recuerda el evento en verso. Las traducciones antiguas discrepan sobre la especie exacta: la Septuaginta y la Vulgata dicen ''mosquitos'', mientras que el Targum y Josefo dicen ''piojos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106746, 'spa', 'Así, de igual modo', 'El adverbio כֵּן que significa ''así, de igual modo'', presente en Isa 51:6, donde los habitantes de la tierra morirán ''así'' (כֵּן), es decir, de la misma manera en que los cielos se disipan como humo y la tierra se desgasta como un vestido. Es léxicamente ajeno al sustantivo de insectos y pertenece a la partícula adverbial común hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106747, 'spa', 'Otorgar título', 'El Piel aparece en cuatro pasajes sobre nombrar y titular. Dios dice a Ciro: «Te he llamado por tu nombre, te he dado título de honor» aunque Ciro no conocía a Yahvé (Is 45:4). Isaías describe cómo el futuro converso «se dará a sí mismo el nombre de Israel» (Is 44:5), tomando el nombre de la alianza como sobrenombre propio. Por el contrario, Elihú declara dos veces que no «adulará» a nadie con títulos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106750, 'spa', 'lira, arpa (instrumento de cuerdas)', 'lira, arpa (instrumento de cuerdas): instrumento de cuerdas portátil que abarca toda la vida musical israelita — celebración pastoril (Gn 31:27), éxtasis profético (1 S 10:5), adoración en el templo (2 Cr 29:25) y lamentación (Job 30:31; Sal 137:2). Frecuentemente emparejado con el ugav (flauta), el tof (pandero) y el nevel (salterio). La iconografía sugiere un instrumento tipo lira con marco asimétrico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106768, 'spa', 'Conías/Jeconías', 'Jeremías usa la forma abreviada כָּנְיָהוּ (Conías) tres veces en los capítulos 22 y 37. En 22:24 y 28, el profeta pronuncia juicio usando esta forma contracta, sugiriendo quizás disminución o rechazo al eliminar el prefijo teofórico ''Yeho-'' que invocaba el nombre de YHWH. Para el capítulo 37:1, Jeconías ya ha sido reemplazado por su tío Sedequías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106769, 'spa', 'Así, en consecuencia', 'Adverbio discursivo arameo que significa ''así, en consecuencia, de la siguiente manera'', utilizado para conectar discursos o acciones referidas con su contexto. Señala hacia atrás en Esdras 6:13 (''hicieron en consecuencia'') y hacia adelante en Esdras 4:8 y 5:4-11 (''escribieron/hablaron de la siguiente manera''). Las cinco apariciones se limitan a las secciones arameas de Esdras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106771, 'spa', 'Levita músico y oficial', 'Primer Crónicas registra a Quenanías (כְּנַנְיָה/כְּנַנְיָהוּ) en dos funciones: dirigiendo la música durante la procesión del arca (15:22, 27) por su habilidad (בַּמַּשָּׂא כִּי־מֵבִין הוּא, ''porque era experto''), y sirviendo como oficial y juez entre los izharitas en la administración de Israel (26:29). La variante ortográfica menor refleja flexibilidad escribal con nombres teofóricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106772, 'spa', 'Reunir, recoger', 'Reunir o recoger cosas o personas (Qal), un término general para juntar. David reunió extranjeros residentes para las obras de cantería (1 Cr 22:2), Ester convocó a los judíos para reunirse y ayunar (Est 4:16), y Dios junta las aguas del mar como en un montón (Sal 33:7). Eclesiastés lo usa dos veces para amasar riquezas y recoger.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106774, 'spa', 'Envolverse, arroparse', 'Envolverse o arroparse (Hitpael reflexivo), uso único en Isaías 28:20 donde una manta demasiado estrecha obliga a ''recogerse'' apretadamente. El salto semántico de ''reunir'' a ''envolverse'' tiene sentido natural: juntar algo en un fardo se extiende naturalmente a envolver el propio cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106776, 'spa', 'Congregar, reunir intensivamente', 'Reunir o congregar con propósito deliberado e intensivo (Piel), frecuentemente con Dios como sujeto. El SEÑOR edifica a Jerusalén y reúne a los exiliados dispersos de Israel (Sal 147:2), y congrega a las naciones en el horno del juicio (Ez 22:21, 39:28). Este sentido se distingue de la recolección más neutra del Qal por su intencionalidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106782, 'spa', 'humillarse ante Dios', 'humillarse ante Dios: Nifal reflexivo, humillarse voluntariamente, especialmente en penitencia ante Dios. El texto paradigmático es 2 Crónicas 7:14: «si mi pueblo se humillare y orare». El arrepentimiento sorpresivo de Acab (1 R 21:29), el corazón tierno de Josías (2 R 22:19) y el llamado levítico a que los corazones incircuncisos «se humillen» (Lv 26:41) expresan autohumillación voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106784, 'spa', 'ser sometido o derrotado', 'ser sometido o derrotado: Nifal pasivo, ser sometido, vencido o abatido, generalmente en derrota militar. Jueces 3:30 registra que Moab «fue sometido» bajo Israel, y Jueces 8:28 reporta lo mismo para Madián. El patrón continúa en Jueces 11:33 y 1 Samuel 7:13. Aquí el sujeto no elige inclinarse; es derribado por una fuerza exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106791, 'spa', 'someter o abatir', 'someter o abatir: Hifil causativo, someter, humillar o abatir a otro por fuerza o decreto divino. Dios promete «someter» a los cananeos delante de Israel (Dt 9:3), David somete a los filisteos (2 S 8:1; 1 Cr 18:1), y Dios humilla a los enemigos de Israel a lo largo de Crónicas. El cambio de autohumillación a humillación impuesta es marcado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106811, 'spa', 'Canaán (nombre propio', 'Canaán (nombre propio: tierra/persona) — El nombre propio Canaán, que designa tanto a la persona (nieto de Noé, hijo de Cam, maldecido en Gn 9:25-27, antepasado de las naciones cananeas enumeradas en Gn 10:15-18) como el territorio geográfico al oeste del Jordán colonizado por Israel. Se transliterá con casi total uniformidad en todas las lenguas — Canaan (ing./fr.), Canaán (esp.), Kanaan (al.) —, lo que confirma su estatus estable como nombre propio en las 89 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106815, 'spa', 'Comerciante, mercader (metonímico) — Un uso metonímico como sustantivo común que', 'Comerciante, mercader (metonímico) — Un uso metonímico como sustantivo común que significa ''comerciante, mercader'', atestiguado una vez en Os 12:7 donde el profeta explota la antigua asociación entre los cananeos/fenicios y el comercio. En español se traduce «Canaán» mientras que en inglés se da «a merchant», revelando cómo las traducciones se dividen entre preservar la forma de nombre propio y hacer explícita la metáfora comercial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106816, 'spa', 'Comerciante', 'El término aparece con sentido mercantil en textos proféticos. Ezequiel usa «tierra de Canaán» para designar «una tierra de mercaderes» donde el águila planta la vid (Ez 17:4) y donde Jerusalén multiplicó su prostitución (Ez 16:29). Sofonías pronuncia juicio sobre «todo el pueblo mercader», literalmente «todo el pueblo de Canaán», que comercia con plata (Sof 1:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106817, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que posiblemente significa ''hacia Canaán'' o comparte la raíz del topónimo Canaán. Identifica al padre del profeta Sedequías, quien confrontó a Micaías antes de la fatídica batalla de Acab en Ramot de Galaad (1 R 22:11, 24; 2 Cr 18:10, 23), y por separado a un descendiente benjamita de Bilhán (1 Cr 7:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106818, 'spa', 'Cananeo (designación étnica) — La designación gentilicia para un miembro del pue', 'Cananeo (designación étnica) — La designación gentilicia para un miembro del pueblo cananeo, los habitantes preisraelitas de la tierra de Canaán. Cubriendo 70 de 71 apariciones, este sentido abarca las narraciones patriarcales (Gn 12:6; 13:7), los relatos de la conquista (Jue 1:1, 3, 9) y las genealogías (Gn 46:10). Las traducciones emplean consistentemente formas gentilicias estándar — español «cananeo», francés «Cananéen», alemán «Kanaaniter» — subrayando su carácter de etnónimo reconocido universalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106833, 'spa', 'Comerciante, mercader — Una extensión metonímica que significa ''comerciante'' o ''', 'Comerciante, mercader — Una extensión metonímica que significa ''comerciante'' o ''mercader'', que refleja la extendida reputación de los cananeos como intermediarios comerciales en todo el antiguo Cercano Oriente. Está atestiguado únicamente en Job 41:6, donde aparece en un contexto mercantil. La evidencia multilingüe es decisiva: el español pasa de «cananeo» a «mercaderes», el inglés de «Canaanite» a «merchants», mientras que el francés y el alemán mantienen la forma hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106836, 'spa', 'Ala de ave o ángel', 'La acepción primaria es el ala física de un ave, querubín, serafín u otro ser alado, presente en la gran mayoría de las apariciones. Incluye las alas del águila de Ex 19:4 y Dt 32:11, las seis alas de los serafines de Is 6:2 y las alas de los querubines cubriendo el arca (1 R 6:24; 8:7). Se extiende crucialmente a la metáfora de las alas protectoras de Dios (Sal 17:8; 36:7; 91:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106842, 'spa', 'Falda o borde de vestido', 'Acepción textil que denota la falda, borde o esquina de un manto: el ''ala'' de la capa que se extendía como gesto de protección pactual. Rt 3:9 y Ez 16:8 usan ''extender la כָּנָף'' sobre alguien como acto de desposorio o compromiso de alianza. Dt 22:30 prohíbe descubrir la כָּנָף del padre (la cobertura de su esposa). El coreano 자락/옷자락 y el árabe طرف/ذيل reflejan esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106847, 'spa', 'Confín o extremo de tierra', 'En el extremo geográfico, כָּנָף designa la esquina, borde o confín de una tierra o de la tierra misma. Job 37:3 y 38:13 hablan de las ''alas de la tierra''; Is 11:12 reúne a los dispersos de las cuatro כַּנְפוֹת de la tierra. Nm 15:38 prescribe borlas en las כַּנְפוֹת de los vestidos, tendiendo un puente entre las acepciones textil y espacial. El árabe أركان/أطراف y el suajili pembe/ncha captan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106887, 'spa', 'Kinnereth', 'Nombre propio geográfico en Galilea, dentro del territorio de Neftalí, que designa tanto una antigua ciudad fortificada (Jos 19:35) como el lago interior junto a ella, יָם כִּנֶּרֶת, el ''Mar de Kinnereth'' (Núm 34:11; Jos 12:3; 13:27), conocido en la era neotestamentaria como el Mar de Galilea. La variante Kinerot/Kinnerot aparece en Jos 11:2 y 1 Re 15:20 para designar la región circundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106892, 'spa', 'Congregar funcionarios', 'Daniel 3:2 emplea el infinitivo ''reunir'' (לְמִכְנַשׁ) a los sátrapas, prefectos y gobernadores para la dedicación de la imagen de oro. Los versículos 3 y 27 usan el participio hitpael מִתְכַּנְּשִׁין, ''se reunieron/congregaron'', representando la convocatoria efectiva de los oficiales. La repetición subraya la magnitud y solemnidad del evento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106894, 'spa', 'Compañeros oficiales', 'Asociado o compañero oficial, usado exclusivamente en las secciones arameas de Esdras para designar a los colegas de administradores provinciales persas como Rehum y Tatnai (Esd 4:9, 17, 23; 5:3, 6; 6:6, 13). El término posee un registro administrativo cuasi-técnico, apareciendo siempre con sufijos posesivos (''sus compañeros'') en el lenguaje formulaico fijo de la correspondencia imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106898, 'spa', 'Trono real', 'El trono real o divino: 125 apariciones, la acepción dominante con gran diferencia. Abarca los tronos de reyes israelitas y extranjeros (Ex 11:5; Dt 17:18; 2 S 3:10), el trono de Dios (Sal 45:6; 93:2; Is 6:1) y el trono como metonimia del gobierno dinástico (''Estableceré su trono para siempre'', 2 S 7:13). El español trono, el francés trône y el alemán Thron seleccionan explícitamente terminología de autoridad real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106904, 'spa', 'Asiento o silla', 'Asiento o silla literal sin connotación real específica: 6 apariciones donde el contexto describe mobiliario ordinario para sentarse. El כִּסֵּא de Elí junto al dintel del tabernáculo (1 S 1:9), del que cae y muere (1 S 4:13, 18), es la silla de un sacerdote anciano, no un trono. La sunamita amuebla la habitación de Eliseo con cama, mesa, כִּסֵּא y lámpara (2 R 4:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106913, 'spa', 'Tronos de autoridad', 'Tronos en plural que representan múltiples sedes de autoridad gobernante o judicial: 4 apariciones. En Sal 122:5 ''allí se establecieron tronos para el juicio, los tronos de la casa de David'', el plural כִּסְאוֹת evoca un estrado judicial o consejo de gobernantes. En Is 14:9 las sombras de reyes muertos se levantan de sus tronos en el Seol; en Ez 26:16 los príncipes del mar descienden de sus tronos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106931, 'spa', 'Cubrir físicamente (Piel)', 'Acepción Piel intensiva de cubrir físicamente una superficie, objeto o persona con un material — tela, tierra, nube, piel, agua o grasa. El árabe غطّى/يُغَطِّي (''cubrir completamente'') y el español cubrir convergen en la cobertura total de superficie. Es la acepción funcional principal con 101 apariciones: las aguas cubriendo los montes en el diluvio (Gn 7:19-20), las ranas cubriendo la tierra de Egipto (Ex 8:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106935, 'spa', 'Ocultar, encubrir (Piel)', 'Acepción Piel de ocultar o encubrir información, culpa o maldad. El árabe ستر (velar), كتم (suprimir) y أخفى (esconder) emplean raíces distintas a la cobertura física, confirmando un genuino desplazamiento semántico. Gn 18:17 pregunta ''¿Encubriré a Abraham lo que voy a hacer?'' Pr 10:18 advierte que quien ''encubre el odio'' con labios mentirosos es necio, mientras que Pr 28:13 promete misericordia al que confiesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106948, 'spa', 'Cubrirse a sí mismo (Hitpael)', 'Acepción reflexiva Hitpael de cubrirse con un vestido, velo o cilicio, ya sea por duelo, modestia o disfraz. El árabe تغطّى (''cubrirse'') y اكتسى (''vestirse'') codifican la acción autodirigida. Rebeca se cubre con un velo al ver a Isaac (Gn 24:65); Ezequías se cubre de cilicio antes de entrar en el templo (2 R 19:1); Pr 26:26 advierte que el odio ''se cubre'' con engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106951, 'spa', 'Ser cubierto (Pual/Nifal)', 'Acepción Pual, Nifal y participio pasivo Qal de estar cubierto: el estado pasivo resultante de la acción de otro. Sal 32:1 es teológicamente central: ''Bienaventurado aquel cuyo pecado es cubierto'' (כְּסוּי חֲטָאָה), donde Dios pone la transgresión fuera de vista. Gn 7:19-20 describe los montes siendo cubiertos por las aguas del diluvio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106952, 'spa', 'Abrumar, envolver (Piel)', 'Acepción Piel de abrumar o envolver: aguas, oscuridad o vergüenza que cubren y sumergen a una persona por completo. El árabe غشي (''abrumar'') y غمر (''inundar'') apuntan a una sumersión catastrófica más que a simple cobertura. Sal 55:5 clama ''el horror me ha envuelto''; Ez 7:18 advierte que ''la vergüenza cubrirá todos los rostros''. La imagen sobrepasa la cobertura para alcanzar la inmersión total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (106968, 'spa', 'Vestir, revestir (Piel)', 'Acepción Piel de cubrir a una persona específicamente con vestiduras, a menudo como acto de cuidado, provisión u honor. El árabe كسا (''vestir a alguien'') preserva la raíz cognada en su sentido específico de vestimenta. Ez 16:10 retrata a Dios vistiendo a Jerusalén con tela bordada y lino fino como acto de amor pactual. Is 58:7 ordena ''cuando veas al desnudo, cúbrelo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107033, 'spa', 'Cubierta, vestidura', 'Cubierta o prenda usada para la protección y el abrigo del cuerpo, que abarca tanto la ropa cotidiana (Éx 21:10; Dt 22:12; Job 24:7; 31:19) como usos figurados o extendidos, tales como la «cubierta de los ojos» que denota vindicación o compensación (Gn 20:16), la cubierta de los cielos con cilicio (Is 50:3) y el descubrimiento del Abadón (Job 26:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107041, 'spa', 'Necio, insensato — Un necio moralmente obtuso que deliberadamente rechaza la sab', 'Necio, insensato — Un necio moralmente obtuso que deliberadamente rechaza la sabiduría y abraza la insensatez; el término principal de reprobación en el marco pedagógico de Proverbios. Se distingue del ''evil'' (''simple'', H0191) y del naval (''necio despreciable'', H5036): el kesil se caracteriza por una estupidez voluntaria más que por mera ignorancia. Odia el conocimiento (Pr 1:22), derrama necedad (Pr 15:2) y desprecia a su madre (Pr 15:20). En español «necio», en francés «insensé» y en alemán «Tor» captan la mezcla de obstinación moral y torpeza intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107049, 'spa', 'Constelación de Orión', 'La constelación aparece en literatura sapiencial y profética que describe el poder creador de Dios. Job enumera a Orión junto a otras constelaciones como evidencia de la sabiduría divina (Job 9:9), y Dios mismo pregunta a Job: «¿Podrás desatar las ligaduras de Orión?» (Job 38:31). Amós exhorta a Israel a buscar a Dios, quien «hizo las Pléyades y Orión» (Amós 5:8). Isaías advierte que las constelaciones de Orión no darán su luz en el juicio venidero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107053, 'spa', 'El sentido anatómico', 'El sentido anatómico: lomos, ijares, el tejido adiposo alrededor de los riñones y la zona lumbar. El árabe al-khasiratain (''los dos flancos'') y el español ''lomos'' convergen con precisión. Las siete ocurrencias aparecen en instrucciones sacrificiales levíticas que especifican qué porciones de grasa se ofrecen sobre el altar (Lv 3:4, 10, 15; 4:9; 7:4), además del lamento del salmista por sus lomos afligidos (Sal 38:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107054, 'spa', 'Confianza, seguridad o firmeza — sentido abstracto quizá derivado de los lomos c', 'Confianza, seguridad o firmeza — sentido abstracto quizá derivado de los lomos como sede percibida de la fuerza interior. El árabe i''timaduhu (''su confianza''), el español ''confianza'' y el inglés ''confidence'' coinciden. Se emplea para la confianza mal puesta que se derrumba como tela de araña (Job 8:14), la confianza adecuada en el SEÑOR (Pr 3:26) y la esperanza de Israel puesta en Dios (Sal 78:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107055, 'spa', 'Necedad, insensatez o estupidez — la extensión más abstracta, quizá derivada de ', 'Necedad, insensatez o estupidez — la extensión más abstracta, quizá derivada de la cualidad ''gruesa, embotada'' asociada metafóricamente con los lomos adiposos. El alemán Torheit (''necedad'') y el español ''necedad'' son inequívocos. Aparece en Eclesiastés 7:25 emparejado con סִכְלוּת mientras el Predicador investiga la naturaleza de la insensatez, y en Salmo 49:13 describiendo el camino autoconfiado de los necios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107063, 'spa', 'Mes noveno', 'Nehemías 1:1 sitúa la conversación decisiva de Nehemías con Hananí ''en el mes de Kislev'' (בְּחֹדֶשׁ כִּסְלֵו/כִּסְלֵיו), desencadenando la reconstrucción de Jerusalén. Zacarías 7:1 fecha una consulta profética en el cuarto año de Darío, en Kislev. La literatura postexílica muestra claramente el uso de nombres de meses babilónicos en lugar del sistema cananeo anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107070, 'spa', 'Espelta como cereal', 'Éxodo 9:32 señala que la espelta (כֻּסֶּמֶת) y el trigo escaparon de la plaga de granizo por ser de maduración tardía (אֲפִילֹת הֵנָּה). Isaías 28:25 la incluye en una lista de granos sembrados cuidadosamente, cada uno en su lugar apropiado. Ezequiel 4:9 la prescribe entre los ingredientes del pan de asedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107072, 'spa', 'Anhelar, desear intensamente', 'Anhelo profundo dirigido hacia una persona, un lugar o Dios. El infinitivo absoluto Nifal en Génesis 31:30 («anhelabas grandemente la casa de tu padre») enfatiza la intensidad mediante la duplicación. En Job 14:15 Dios anhela la obra de sus manos, y Salmo 84:2 transforma la palabra en devoción espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107078, 'spa', 'plata (el metal)', 'El metal precioso en su sentido físico: como mineral en bruto, material refinado o sustancia trabajada para mobiliario del templo, ídolos, joyas y ornamentación. Abarca la gran mayoría de las ocurrencias (391x). Contextos clave incluyen la construcción del tabernáculo (Éxodo 25-38) y la imaginería profética de refinar plata (Zac 13:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107091, 'spa', 'dinero, precio de compra', 'La plata funcionando como dinero, moneda o precio de compra (12x), pesada en transacciones comerciales, salarios, multas o pagos de redención. Los sufijos posesivos (''su plata,'' ''nuestra plata'') marcan este sentido de modo distintivo, como cuando los hermanos de José descubren su dinero devuelto (Gn 42:25-35). El alemán Geld frente a Silber señala con nitidez el paso de sustancia a moneda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107118, 'spa', 'Plata como metal precioso y como dinero (כְּסַף, arameo)', 'Plata como metal precioso y como dinero (כְּסַף, arameo). En Daniel designa la sustancia física: el pecho de plata de la gran estatua (Dan 2:32, 35, 45) y los vasos de plata del templo (Dan 5:2, 4, 23; Esd 5:14; 6:5). En Esdras funciona como moneda en concesiones reales para el templo de Jerusalén (Esd 7:15–18, 22). El español ''plata'' y el francés ''argent'' preservan igualmente tanto el sentido material como el monetario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107124, 'spa', 'Adverbio temporal arameo ''ahora'' (כְּעַן), que marca el tiempo presente o introd', 'Adverbio temporal arameo ''ahora'' (כְּעַן), que marca el tiempo presente o introduce una transición lógica en el discurso. En cartas oficiales funciona como ''ahora pues'', abriendo nuevas directivas (Esd 4:13–14, 21; 5:17; 6:6). En la narrativa y la oración señala el momento presente: la acción de gracias de Daniel (Dan 2:23), los desafíos reales (Dan 3:15) y la restauración de Nabucodonosor (Dan 4:37). La frase עַד־כְּעַן ''hasta ahora'' (Esd 5:16) extiende el sentido para indicar duración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107126, 'spa', 'Fórmula epistolar', 'La frase aparece cuatro veces en cartas oficiales dentro de los capítulos arameos de Esdras. Introduce el cuerpo de la carta de Rejum y Simsai: «y ahora, sea conocido al rey...» (Esd 4:11-12). El rey Artajerjes inicia su respuesta: «y ahora, la carta que enviasteis...» (Esd 4:17). Una carta real posterior comienza: «y ahora, yo decreto...» (Esd 7:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107127, 'spa', 'Provocar a ira (causativo)', 'Provocar a ira (causativo): el uso dominante en Hifil y Piel teológico, donde se provoca a alguien — abrumadoramente a Dios — a ira mediante la idolatría, el pecado o la rebelión. Es el lenguaje del juicio de pacto: ''me provocaron a ira con sus ídolos'' (Dt 32:16, 21). Casi todas las apariciones en Reyes emplean este sentido para explicar por qué sobrevino el juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107132, 'spa', 'Estar enojado o irritado', 'Estar enojado o irritado: el sentido intransitivo del Qal, estar airado, irritado o angustiado emocionalmente sin dirigir esa ira hacia otro. Asá ''se enojó'' contra el vidente (2 Cr 16:10), el malvado ''se irrita'' al ver prosperar al justo (Sal 112:10), y Qohélet aconseja paciencia antes que la ira precipitada (Ec 7:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107145, 'spa', 'Provocar o atormentar interpersonalmente', 'Provocar o atormentar interpersonalmente: un uso especializado en la narrativa de Penina y Ana (1 S 1:6–7), donde se hostiga, provoca o atormenta a otra persona por rivalidad. Aquí la provocación no es teológica sino relacional — una esposa rival que deliberadamente aguijonea a una mujer estéril hasta las lágrimas, haciendo de este sentido algo singularmente personal y doméstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107170, 'spa', 'Vejación interior, pesar o aflicción', 'Vejación interior, pesar o aflicción: la angustia emocional que se asienta sobre quien ha sido herido o defraudado. La oración afligida de Ana brota de su כַּעַס (1 Sam 1:16), y el ojo del salmista se consume ''de dolor'' (Sal 6:7; 31:9). Este sentido captura la dimensión de sufrimiento íntimo, el peso que oprime el corazón sin necesariamente dirigirse hacia afuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107172, 'spa', 'Ira activa, indignación o enojo dirigido hacia afuera, no la causa de la ira sin', 'Ira activa, indignación o enojo dirigido hacia afuera, no la causa de la ira sino la ira misma como emoción ardiente. Proverbios 12:16 advierte que el כַּעַס del necio se conoce al instante, y el Salmo 85:4 pide a Dios que cese su enojo hacia su pueblo. Pasajes clave: Proverbios 21:19; 27:3; Eclesiastés 7:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107173, 'spa', 'Provocación, el acto u ocasión de incitar a alguien a la ira, especialmente en l', 'Provocación, el acto u ocasión de incitar a alguien a la ira, especialmente en la fórmula deuteronomista donde la idolatría de Israel ''provoca'' a Dios. La cadena constructa en Ezequiel 20:28 convierte el sacrificio idolátrico en el irritante mismo. Pasajes clave: Deuteronomio 32:19, 27; 1 Reyes 15:30; 2 Reyes 23:26.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107188, 'spa', 'Vejación e ira', 'El término aparece cuatro veces en Job describiendo vejación e ira. Elifaz advierte que «la vejación mata al necio» (Job 5:2, en paralelo con la envidia). Job lamenta: «¡Oh, si se pesara mi aflicción!» junto a su calamidad (Job 6:2). Job acusa a Dios: «Renuevas tu furor contra mí» (Job 10:17). Un consejero anciano observa que la «indignación» es impropia en los ancianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107189, 'spa', 'palma de la mano', 'La palma abierta o mano, con diferencia el sentido dominante. Cubre acciones de agarrar, sostener, golpear, aplaudir, extender en oración y colocar objetos sobre la palma. Gn 40:11 presenta al copero exprimiendo uvas en la כַּף del faraón; Lv 8:27 coloca ofrendas sobre las כַּפַּיִם de Aarón. El árabe kaff y el alemán Handfläche confirman el significado anatómico primario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107198, 'spa', 'planta del pie', 'La planta o superficie inferior del pie, distinguida de la palma por el contexto (a menudo con רֶגֶל, ''pie''). Gn 8:9 registra a la paloma sin hallar lugar de reposo para ''la planta de su pie,'' y la fórmula territorial de Deuteronomio promete ''todo lugar que pise la planta de vuestro pie'' (Dt 11:24). El coreano balbadak (planta del pie) frente a sonbadak (palma) ilustra cómo las lenguas receptoras separan ambos referentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107216, 'spa', 'cucharilla o recipiente', 'Un utensilio cúltico con forma de palma: cucharilla, plato o cuchara usada para incienso y ofrendas en el tabernáculo y el templo. Nm 7:84-86 contabiliza doce כַּפּוֹת de oro llenas de incienso. La forma hueca y abierta del recipiente motiva la extensión metafórica de la parte del cuerpo al objeto ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107221, 'spa', 'cavidad de la cadera', 'El hueco de la articulación del muslo o la cavidad de la cadera, exclusivamente en la narración de la lucha de Jacob (Gn 32:25, 32). El ángel golpea la כַּף del muslo de Jacob, dislocándolo. La lógica formal persiste: כַּף es la cavidad cóncava en la que encaja la cabeza del fémur.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107244, 'spa', 'pata de animal', 'La pata de un animal: en Lv 11:27, las criaturas que ''andan sobre sus patas'' (כַּפַּיִם). La superficie plana y acolchada de la pata del animal refleja la palma humana, lo que hace natural la transferencia semántica del cuerpo humano al zoológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107245, 'spa', 'manija o asidero', 'La manija o empuñadura de un cerrojo, como en Cnt 5:5, donde las manos de la amada destilan mirra ''sobre las manijas del cerrojo.'' La superficie cóncava del asidero lo conecta con el prototipo de la palma ahuecada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107271, 'spa', 'ramas de palmera', 'Ramas o frondes de palmera datilera, como en Lv 23:40, donde se ordena a Israel tomar ''ramas de palmeras'' (כַּפּוֹת תְּמָרִים) para la Fiesta de los Tabernáculos. La forma ancha y plana de la hoja de palmera motiva que reciba el nombre de la mano abierta, una vívida metáfora formal conservada en las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107294, 'spa', 'Fronda de palmera', 'Isaías 9:14 y 19:15 emplean una frase idéntica: ''cabeza y cola, rama de palmera y junco'' (רֹאשׁ וְזָנָב כִּפָּה וְאַגְמוֹן), un merismo que abarca todos los estratos sociales. La silueta alta y coronada de la palmera simboliza naturalmente el estatus elevado. Job 15:32 predice que la כִּפָּה del impío no estará verde, negándole la vitalidad emblemática de la palmera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107295, 'spa', 'Tazón, recipiente sagrado', 'Tazón o recipiente de oro o plata que servía como vaso sagrado en el culto israelita del templo. Aparece exclusivamente en textos tardíos: 1 Crónicas 28:17 (seis veces en el pasaje, detallando las especificaciones de David para tazones de oro y plata pesados con exactitud) y Esdras 1:10 y 8:27 (enumerando los utensilios devueltos del cautiverio babilónico).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107300, 'spa', 'Escarcha blanca', 'Éxodo 16:14 describe la apariencia del maná con un doble símil: ''fino como la escarcha sobre la tierra'' (דַּק כַּכְּפֹר), resaltando su cualidad delicada y cristalina. Job 38:29 pregunta retóricamente quién engendró la escarcha del cielo. Salmo 147:16 alaba a Dios que ''esparce la escarcha como ceniza'' (יִתֵּן כְּפוֹר כָּאֵפֶר). La imagen es consistentemente visual: blanca, fina y efímera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107302, 'spa', 'león joven, cachorro de león', 'león joven, cachorro de león: un león joven o adolescente que ya superó la etapa de cachorro indefenso pero aún no es adulto con melena completa, capaz de cazar presas. Sansón encuentra uno en Timnat (Jue 14:5). Ezequiel alegoriza a los príncipes de Judá como leones jóvenes entrenados para devorar (Ez 19:2-6). Los Salmos usan la imagen para el peligro acechante (Sal 17:12) y la provisión divina que supera la fuerza del león (Sal 34:10). La visión mesiánica de Isaías coloca al león joven junto al becerro (Is 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107323, 'spa', 'Ciudad gabaonita', 'Quefirá aparece en relatos de conquista y asentamiento. Josué descubrió que era una de las cuatro ciudades gabaonitas que lo habían engañado (Jos 9:17). Fue asignada a la herencia de Benjamín (Jos 18:26). Los censos registran su población tras el exilio: los hombres de Quefirá y Beerot sumaban 743 en el primer retorno (Esd 2:25) y 621 en la lista paralela de Nehemías (Neh 7:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107324, 'spa', 'Doblar, plegar', 'Doblar o plegar, especialmente telas en la construccion cultual. El Qal activo aparece en Exodo 26:9 para plegar la cortina del tabernaculo, mientras que el participio pasivo en Exodo 28:16 y 39:9 describe el pectoral sacerdotal como ''doblado en dos'' (כָּפוּל). Ezequiel 21:14 extiende la imagen metaforicamente a la espada del juicio divino que debe ser ''doblada'', intensificando la sentencia profetica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107325, 'spa', 'Doble o duplo', 'Job 11:6 declara que la sabiduría profunda es ''doble en esencia'' (כִּפְלַיִם לְתוּשִׁיָּה), muy por encima de lo que Job percibe. Job 41:13 pregunta quién puede penetrar ''el doble de su freno'' (בְּכֶפֶל רִסְנוֹ), la impenetrable estructura mandibular de Leviatán. Isaías 40:2 promete que Jerusalén ha ''recibido el doble por todos sus pecados'' (כִּפְלַיִם בְּכָל־חַטֹּאתֶיהָ), significando restauración plena y abundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107328, 'spa', 'Encorvar, inclinarse', 'Encorvar, inclinar o estar encorvado, describiendo la postura fisica bajo afliccion o en adoracion. En el Salmo 57:6 e Isaias 58:5, la inclinacion es metafora del sufrimiento o la humildad ritual. El participio pasivo en Salmos 145:14 y 146:8 designa a los afligidos que Dios levanta con ternura. Miqueas 6:6 usa el nifal reflexivo para inclinarse ante Dios en acto de culto solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107329, 'spa', 'expiación ritual (Piel)', 'El sentido abrumadoramente dominante: expiación cúltica en Piel, que representa más del 80% de las ocurrencias. La fórmula levítica ''y el sacerdote hará expiación por él, y será perdonado'' (Lv 4:26, 31, 35) constituye el patrón definitorio. El árabe كَفَّرَ (cognado exacto) y el francés expier preservan la cualidad expiatoria performativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107336, 'spa', 'ser expiado (Pual/Hitpael)', 'Troncos pasivo y reflexivo-pasivo (Pual, Hitpael, Nitpael): que se haga expiación en favor de alguien o ser perdonado. Nm 35:33 advierte que la tierra no puede ser expiada sino con sangre; 1 S 3:14 declara que la casa de Elí jamás será expiada. El uso de Dt 21:8 muestra a la comunidad recibiendo expiación mediante el ritual de la becerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107338, 'spa', 'rescate imposible', 'Una única ocurrencia en Is 47:11, donde el desastre cae sobre Babilonia y ''no podrás expiarla'': ningún pago de cobertura ni rescate podrá evitarlo. El contexto no es cúltico sino la imposibilidad de comprar la liberación del juicio divino. Este matiz transaccional de ''rescate'' conecta con el sustantivo כֹּפֶר (precio de rescate).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107341, 'spa', 'perdonar directamente (Piel)', 'Perdón divino sin ritual sacrificial explícito: Dios como sujeto perdonando directamente el pecado. Sal 78:38 (''sin embargo él, siendo compasivo, expió su iniquidad'') y Sal 79:9 sitúan a Dios mismo como agente del cubrimiento. Este sentido anticipa la crítica profética que trasciende el rito hacia la misericordia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107352, 'spa', 'apaciguar a una persona', 'Apaciguamiento entre personas: Jacob busca ''cubrir el rostro'' de Esaú con presentes antes de su reunión (Gn 32:20), y Pr 16:14 observa que un hombre sabio apacigua la ira del rey. La metáfora subyacente de cubrir el rostro del ofendido preserva la etimología raíz de modo más transparente que la terminología ritual desarrollada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107364, 'spa', 'cubrir, ocultar el pecado', 'El sentido etimológico de cubrir u ocultar el pecado, más cercano al significado físico raíz. Jr 18:23 (''no cubras su iniquidad'') y Dn 9:24 (''para expiar la iniquidad'') se centran en que el pecado mismo quede oculto de la vista, más que en un procedimiento ritual. Muchos estudiosos consideran este el núcleo semántico original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107371, 'spa', 'anular un pacto', 'Una única ocurrencia en Is 28:18, donde Dios declara que el pacto con la muerte ''será anulado.'' El sentido apunta a una cancelación legal: el acuerdo de cobertura o expiación queda invalidado. Este uso extiende la metáfora raíz del cubrimiento hacia su reverso: una cobertura inválida es retirada, dejando a las partes expuestas al juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107374, 'spa', 'Sentido legal y teológico principal de un rescate o precio de redención pagado p', 'Sentido legal y teológico principal de un rescate o precio de redención pagado para salvar una vida de la muerte o del castigo. El Código de la Alianza lo prescribe como el pago que debe hacer el dueño de un buey cuando su animal mata a una persona (Éx 21:30). La legislación sacerdotal lo exige como impuesto censal para evitar la plaga (Éx 30:12) y lo prohíbe firmemente para los homicidas (Núm 35:31-32). En la literatura sapiencial, Job 33:24 y Sal 49:8 lo presentan como el precio que nadie puede pagar para redimir su propia alma ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107375, 'spa', 'Sentido negativo especializado donde el ''rescate'' se convierte en soborno destin', 'Sentido negativo especializado donde el ''rescate'' se convierte en soborno destinado a pervertir la justicia en lugar de asegurar una redención legítima. El discurso de despedida de Samuel (1 Sam 12:3) desafía a Israel a testificar si alguna vez aceptó soborno, usando kopher en paralelo con ''cegar los ojos''. Amós 5:12 acusa a los poderosos de aceptar sobornos para rechazar al pobre en la puerta. La evidencia multilingüe marca esta distinción claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107381, 'spa', 'Las expiaciones', 'Expiación o propiciación ritual: el sustantivo abstracto plural que designa el proceso sacerdotal de cubrir el pecado y restaurar la relación correcta con Dios. Usado exclusivamente en contextos de la fuente Sacerdotal: el Día de la Expiación (יוֹם הַכִּפֻּרִים, Lev 23:27-28; 25:9), la ofrenda por el pecado de expiación (Éx 30:10; Núm 29:11), el carnero de expiación (Núm 5:8) y el dinero de expiación (Éx 30:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107385, 'spa', 'La plancha propiciatoria de oro que cubría el Arca del Pacto, flanqueada por dos', 'La plancha propiciatoria de oro que cubría el Arca del Pacto, flanqueada por dos querubines cuyas alas extendidas formaban el trono de la presencia de YHWH (Éx 25:17-22). Funcionaba como punto focal de la expiación en Yom Kippur, cuando el sumo sacerdote rociaba sangre sobre ella para purgar los pecados de Israel (Lv 16:14-15). Dios hablaba a Moisés ''de encima del propiciatorio, de entre los dos querubines'' (Éx 25:22; Nm 7:89).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107392, 'spa', 'Atar con ligaduras', 'El verbo aparece cuatro veces en la narración del horno ardiente. Nabucodonosor ordenó a hombres robustos «atar» a Sadrac, Mesac y Abednego (Dan 3:20). El pasivo Pe''il registra que «fueron atados» con sus vestiduras y arrojados al horno (Dan 3:21). El participio pasivo Pa''el los describe como «atados» al ser lanzados dentro (Dan 3:23), y enfatiza la preservación milagrosa cuando el rey asombrado los vio libres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107393, 'spa', 'Cáliz, botón del candelabro', 'Cáliz, botón del candelabro. Un bulbo ornamental o botón en forma de capullo en el candelabro de oro (menorá), parte del esquema decorativo de flor de almendro descrito en las narrativas de construcción del tabernáculo (Éx 25:31-36, 37:17-22). Cada brazo tiene tres copas en forma de flor de almendro, cada una con su cáliz y su flor. La Septuaginta lo traduce como ''esfera'', Josefo como ''pequeña granada'' y la Vulgata como ''sphaerula''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107397, 'spa', 'Capitel de columna', 'Capitel de columna. El capitel o pieza que corona una columna, un término arquitectónico. En Amós 9:1, Dios ordena golpear los capiteles para que tiemblen los umbrales, una visión de destrucción catastrófica del templo. Sofonías 2:14 retrata a Nínive desolada con animales alojándose entre capiteles en ruinas. El vínculo semántico con el sentido 1 es la idea de una protuberancia redondeada sobre una estructura vertical, pero el referente cambia del mobiliario cultual a la arquitectura monumental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107399, 'spa', 'Patria de los filisteos', 'Deuteronomio 2:23 identifica a los caftoreos como quienes destruyeron a los aveos cerca de Gaza, estableciendo la presencia filistea. Jeremías 47:4 habla del ''remanente de la costa de Caftor'' (שְׁאֵרִית אִי כַּפְתֹּר) en un oráculo contra Filistea. Amós 9:7 equipara retóricamente el éxodo filisteo desde Caftor con el de Israel desde Egipto. La mayoría de los estudiosos modernos identifican Caftor con Creta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107400, 'spa', 'Pueblo de Caftor', 'Génesis 10:14 (= 1 Crónicas 1:12) enumera a los caftoreos entre los descendientes de Mizraim en la Tabla de las Naciones, mostrando conexiones genealógico-geográficas. Deuteronomio 2:23 describe a los כַּפְתֹּרִים como destructores de los aveos que habitaban en aldeas cerca de Gaza, explicando los orígenes territoriales filisteos. El gentilicio los identifica como un grupo étnico diferenciado cuya migración configuró la geopolítica levantina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107402, 'spa', 'Pradera de pastoreo', 'El Salmo 65:13 pinta un cuadro exuberante: «Los כָּרִים se visten de rebaños», como parte de un himno a la creación. El Salmo 37:20 usa כָּרִים en paralelo con el humo para describir la fugacidad de los impíos. Isaías 30:23 promete «pasto espacioso» (כַּר נִרְחָב) para el ganado, señal de prosperidad agrícola. La conexión con «cordero» enriquece la imagen pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107403, 'spa', 'Ariete de asedio', 'Ariete, la pesada máquina de asedio usada para abrir brechas en murallas y fortificaciones urbanas. Las tres apariciones se concentran en los oráculos de asedio de Ezequiel: Ez 4:2 describe la colocación de arietes contra una maqueta de Jerusalén, y Ez 21:22 los menciona dos veces cuando el rey de Babilonia dispone arietes contra las puertas. El español ''ariete'' (del latín aries, que también significa ''carnero'') refleja perfectamente la extensión semántica del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107404, 'spa', 'Cordero, carnero', 'Cordero o carnero joven, macho de oveja valorado por su grasa abundante y su carne tierna. Deuteronomio 32:14 celebra ''la grasa de los corderos'' junto con el trigo más fino, mientras que 2 Reyes 3:4 registra a Mesa de Moab entregando 100.000 corderos como tributo. Isaías 34:6 empareja la sangre de los corderos con escenas de sacrificio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107411, 'spa', 'Cor (medida de capacidad)', 'Unidad volumétrica grande para medir grano, harina y ocasionalmente aceite, equivalente a unos 220 litros. La corte de Salomón consumía treinta cors de flor de harina al día (1 R 4:22); Hiram suministró veinte mil cors de trigo (2 Cr 2:10); y en Ezequiel 45:14 el cor se emplea también como medida de líquidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107418, 'spa', 'Cavar, excavar', 'Cavar, excavar. El sentido primario en Qal de cavar o excavar: pozos, fosas, cisternas y tumbas. Esto abarca la gran mayoría de las apariciones y recorre todo el arco narrativo: el siervo de Abraham cava un pozo (Gn 26:25), Jacob prepara su propia tumba (Gn 50:5), la Ley regula las fosas abiertas (Éx 21:33), los líderes de Israel cavan el pozo en el cántico del desierto (Nm 21:18), y Asa es sepultado en una tumba que había cavado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107423, 'spa', 'Ser cavado', 'Ser cavado. Sentido pasivo en Nifal: ser cavado o excavado, atestiguado en el Salmo 94:13, que habla de dar descanso en los días de aflicción ''hasta que sea cavada una fosa para el impío''. La forma pasiva destaca el resultado más que el agente, encajando en un contexto donde la providencia divina prepara silenciosamente el juicio mientras los justos esperan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107427, 'spa', 'Negociar, comerciar', 'Negociar, comerciar. Un sentido secundario de negociar, comerciar o regatear, atestiguado en Job 6:27 y 41:6. En el primero, Job acusa a sus amigos de estar dispuestos a ''negociar'' con un huérfano; en el segundo, la pregunta es si los mercaderes ''negociarán'' por Leviatán. El vínculo semántico con cavar puede residir en la metáfora de ''escarbar'' en un trato o ''excavar'' beneficios de una transacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107430, 'spa', 'Abrir, perforar', 'Abrir, perforar. Una extensión figurada que significa abrir o perforar, usada en el Salmo 40:6 (TM 40:7) donde Dios ''abrió'' los oídos del salmista, una imagen vívida de hacer a alguien receptivo para escuchar. Este versículo es citado en Hebreos 10:5 (mediante la LXX: ''un cuerpo me preparaste''), lo que convierte esta única aparición en un puente teológico fundamental entre el Antiguo y el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107437, 'spa', 'Querubín, ser guardián angélico', 'Querubín, ser guardián angélico: ser sobrenatural alado apostado en el umbral entre lo divino y lo terrenal, sirviendo como guardián del espacio sagrado y portador de la presencia del trono de Dios. Aparecen custodiando el Edén (Gn 3:24), sobre el Arca (Éx 25:18–20), en todo el Templo de Salomón (1 R 6:23–28) y como las criaturas vivientes del carro-trono de Ezequiel (Ez 10). La transliteración uniforme entre idiomas — español ''querubines'', francés ''chérubins'' — refleja un ser sin equivalente cercano en el lenguaje ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107454, 'spa', 'Guardia real caria', 'En 2 Reyes 11:4, 19 los caritas (הַכָּרִי) aparecen junto a «los corredores» (הָרָצִים) en la coronación orquestada por Joiada. Su vinculación con los cereteos en 2 Samuel 20:23 los conecta con las unidades extranjeras de David. La designación étnica apunta a un origen cario, pueblos navegantes del suroeste de Asia Menor empleados como mercenarios de confianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107456, 'spa', 'Carta de divorcio', 'El término aparece en contextos legales y proféticos sobre el divorcio. Deuteronomio ordena que el hombre que repudia a su esposa le escriba una ''carta de divorcio'' y se la entregue (Dt 24:1, 3). Isaías pregunta retóricamente: ''¿Dónde está la carta de divorcio de vuestra madre?'' (Is 50:1), insinuando que Dios no ha repudiado a Israel. Jeremías declara que Dios entregó la carta de divorcio a la rebelde Israel por su infidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107459, 'spa', 'Ciudad del Éufrates', 'Isaías 10:9 enumera a Carquemis entre las ciudades conquistadas en la jactancia de Asiria: «¿No es Calno como Carquemis?» 2 Crónicas 35:20 relata el enfrentamiento fatal de Josías con Necao «en Carquemis junto al Éufrates» (בְּכַרְכְּמִישׁ עַל־פְּרָת). Jeremías 46:2 data la victoria aplastante de Nabucodonosor, un punto de inflexión que puso fin al dominio egipcio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107462, 'spa', 'Viña, terreno de cultivo de uvas', 'Viña, terreno de cultivo de uvas: parcela cultivada para el cultivo de vides, central en la agricultura, la economía y el simbolismo religioso de Israel. Desde la primera plantación de Noé (Gn 9:20), pasando por las leyes del Deuteronomio, hasta la imaginería profética de Isaías 5, la viña funciona tanto como tierra de labranza literal como potente metáfora del pueblo de Dios. Las traducciones en español (''viña''), francés (''vigne'') y alemán (''Weinberg'') reflejan uniformemente su significado agrícola directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107500, 'spa', 'Vinador, cultivador de vides', 'Vinador o cuidador de vides, cuyo sustento es el cultivo de la vid. Aparece siempre como participio Qal plural y emparejado con labradores (אִכָּרִים/יֹגְבִים) en 2 Re 25:12, Jer 52:16, Joel 1:11 y 2 Cr 26:10. El termino adquiere peso teologico en Isaias 61:5, donde extranjeros serviran como vinadore de Israel en la era mesianica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107501, 'spa', 'Carmi (nombre propio)', 'Nombre personal que posiblemente significa «mi viña», portado por dos personajes bíblicos. El Carmi rubenita aparece entre los hijos de Jacob que descendieron a Egipto (Gn 46:9; Éx 6:14; Nm 26:6; 1 Cr 5:3). El Carmi judahíta es padre de Acán, cuyo robo trajo desastre en Hai (Jos 7:1, 18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107505, 'spa', 'Tinte y tela roja', '2 Crónicas menciona el carmesí (כַּרְמִיל) tres veces en contextos de construcción del templo: 2:6, 2:13 y 3:14, siempre junto al azul (תְּכֵלֶת), la púrpura (אַרְגָּמָן) y el lino fino (בּוּץ). Su agrupación con estos textiles de lujo lo marca como material de primera calidad para el espacio sagrado. Algunos eruditos leen כַּרְמִיל en lugar de כַּרְמֶל en Cantares 7:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107506, 'spa', 'Campo fértil, tierra cultivada', 'Campo fértil, tierra cultivada. Un área cultivada y fértil como un huerto, plantación o tierra de jardín, frecuentemente contrastada con el desierto o el bosque. Isaías la usa en contrastes llamativos: el Líbano se convierte en campo fértil y el campo fértil en bosque (Is 29:17; 32:15). Jeremías 4:26 lamenta que el karmel se ha vuelto desierto. ''Campo fértil'' en español capta la abundancia agrícola del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107511, 'spa', 'Grano fresco, espiga tierna', 'Grano fresco, espiga tierna. Grano fresco, espigas recién maduradas o cereales sin tostar, usado en las regulaciones de ofrendas de grano. Levítico 2:14 prescribe traer karmel de espigas frescas como ofrenda de primicias, y 2 Reyes 4:42 registra a un hombre que trae pan y karmel a Eliseo. ''Espiga fresca'' y ''grano fresco'' en español hacen clara la especificidad agrícola, distinguiendo este sentido del más amplio campo fértil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107519, 'spa', 'El nombre propio Carmelo, que designa ya sea el Monte Carmelo en la costa medite', 'El nombre propio Carmelo, que designa ya sea el Monte Carmelo en la costa mediterránea (escenario de la confrontación de Elías, 1 Re 18:19) o la ciudad de Carmelo en la serranía de Judá (1 Sam 25:2). Los profetas invocan el Carmelo junto con el Líbano, Sarón y Basán como símbolos de la riqueza de la tierra (Is 33:9; Jer 46:18; Am 1:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107521, 'spa', 'Sustantivo común que significa tierra fértil, campo fructífero o huerto, reflejo', 'Sustantivo común que significa tierra fértil, campo fructífero o huerto, reflejo de la proverbial fertilidad de la región del Carmelo. En 2 Cr 26:10 Uzías tiene labradores en el כַּרְמֶל porque ama la tierra. Miqueas 7:14 puede evocar deliberadamente tanto el lugar como la metáfora, pidiendo a Dios que pastoree a Israel en pasto fértil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107532, 'spa', 'Gentilicio de Carmel', 'Adjetivo gentilicio con articulo que significa ''el carmelita'', identificando a una persona como originaria de Carmel en Juda. Nabal es llamado ''el carmelita'' en 1 Sam 30:5, 2 Sam 2:2 y 2 Sam 3:3, vinculandolo a su hacienda en la serrania judea donde famosamente rechazo a David. El guerrero Hezrai/Hezro lleva la misma designacion en el registro de los valientes (2 Sam 23:35 = 1 Cr 11:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107535, 'spa', 'Trono real y divino', 'Daniel 5:20 describe a Nabucodonosor depuesto «de su trono real» (כָּרְסֵא מַלְכוּתֵהּ) cuando su corazón se ensoberbeció. Daniel 7:9 emplea singular y plural: «tronos fueron puestos» (כָּרְסָוָן רְמִיו) y «su trono» (כָּרְסְיֵהּ) era llamas de fuego. El plural puede aludir a tronos para la corte angélica, mientras el singular designa el asiento supremo del Anciano de Días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107537, 'spa', 'inclinarse, arrodillarse (adoración/sumisión)', 'inclinarse, arrodillarse (adoración/sumisión): inclinarse o arrodillarse en adoración, reverencia o sumisión — el sentido dominante, cubriendo el acto deliberado y respetuoso de arrodillarse ante Dios o una autoridad humana. Salomón se arrodilla ante el altar tras su oración (1 R 8:54), Esdras cae de rodillas en penitencia (Esd 9:5), y el Salmo 95:6 invita a la adoración colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107541, 'spa', 'derribar, someter (causativo)', 'derribar, someter (causativo): el Hifil causativo, donde el sujeto obliga a otro a inclinarse o caer. David alaba a Dios: «Sometiste bajo mí a los que se levantaron contra mí» (2 S 22:40 / Sal 18:39). El Salmo 17:13 suplica que Dios «lo derribe». Jueces 11:35 extiende la imagen a la devastación emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107544, 'spa', 'flaquear, ceder (de las rodillas)', 'flaquear, ceder (de las rodillas): las rodillas que ceden o flaquean por debilidad — un participio Qal que describe colapso físico involuntario en vez de arrodillamiento intencional. Job 4:4 habla de fortalecer «las rodillas que flaquean», y Job 39:3 describe un animal parturiento que se agacha. La imagen pasa de la reverencia a la fragilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107564, 'spa', 'agazaparse, agacharse (postura animal)', 'agazaparse, agacharse (postura animal): agazaparse como un animal — la postura de un león que se agazapa antes de saltar. Génesis 49:9 retrata a Judá como un león que «se agazapó», y el oráculo de Balaam en Números 24:9 repite la imagen. Es una postura depredadora, no de adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107569, 'spa', 'Pata de animal', 'Parte inferior de la pata de un animal, que aparece solo en forma dual en contextos rituales o alimentarios. En la legislación sacerdotal (Éx 12:9; 29:17; Lv 1:9, 13; 4:11; 8:21; 9:14), las patas se lavan y se ofrecen con las entrañas en holocaustos. Amós 3:12 la usa como metáfora de destrucción y Levítico 11:21 la aplica a las langostas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107580, 'spa', 'exterminar (Hifil causativo)', 'Hifil causativo: hacer que sea cortado, es decir, destruir, exterminar o eliminar por autoridad divina o real. Las 81 ocurrencias en Hifil portan el mayor peso teológico: Dios cortando activamente a los idólatras (Lv 20:3, 5, 6), el culto falso (Lv 26:30) y naciones enteras. El árabe أَبادَ (aniquilar) capta la agencia intensificada del tronco causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107581, 'spa', 'ser cortado (Nifal)', 'Nifal pasivo-reflexivo: ser cortado del propio pueblo, tierra o vida. Con 74 ocurrencias, constituye la fórmula penal estándar de la legislación sacerdotal: ''aquella persona será cortada de Israel'' (Éx 12:15, 19; 30:33, 38). La voz pasiva enfatiza el resultado más que el agente, aunque se sobrentiende a Dios como causa implícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107582, 'spa', 'cortar un pacto', 'El modismo pactal: ''cortar'' (כָּרַת) un pacto, tratado o acuerdo. Con 97 ocurrencias, este es el uso más frecuente del verbo, reflejando la centralidad de la alianza en la teología bíblica. Gn 15:18 (''aquel día el SEÑOR cortó un pacto con Abram'') es el caso paradigmático, donde el corte literal de animales (Gn 15:10, 17) da origen al modismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107598, 'spa', 'cortar físicamente', 'Qal literal: cortar, talar o derribar físicamente árboles, ramas u objetos materiales. Las 35 ocurrencias incluyen talar postes de Aserá (Éx 34:13), cortar un racimo de uvas (Nm 13:23-24), cortar árboles para obras de asedio (Dt 20:19-20) y la prohibición de castración (Lv 22:24). El hindi kaata, el suajili -kata y el coreano jallada emplean verbos básicos de corte físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107669, 'spa', 'haber sido cortado (Hofal)', 'Hofal causativo pasivo y Qal pasivo: haber sido cortado o talado, enfatizando el estado consumado de separación o destrucción. Solo 3 ocurrencias: Jue 6:28 (la Aserá ''había sido derribada''), Ez 16:4 (''tu cordón umbilical no fue cortado'') y Jl 1:9 (''la ofrenda de cereal fue cortada de la casa del SEÑOR'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107739, 'spa', 'Vigas de cedro', '1 Reyes 6:36 describe la construcción del muro del atrio interior: tres hileras de piedra tallada y «una hilera de vigas de cedro» (כָּרֻתוֹת אֲרָזִים). La misma frase aparece en 7:12 para el gran atrio y el vestíbulo del templo. En 7:2 se mencionan «cuatro hileras de columnas de cedro con vigas de cedro sobre ellas» para la Casa del Bosque del Líbano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107740, 'spa', 'Quereteo(s)', 'Adjetivo gentilicio usado como sustantivo para designar a los quereteos (cereteos), un grupo etnico asociado con la poblacion filistea o parte de ella, posiblemente originario de Creta. La LXX los identifica explicitamente como Krētas (''cretenses'') en Ez 25:16 y Sof 2:5. En Samuel-Reyes sirven como guardia real de David en la expresion fija hakkĕrētî wĕhappĕlētî (''los quereteos y los peleteos'', 2 Sam 8:18; 15:18; 20:7, 23; 1 Re 1:38, 44).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107747, 'spa', 'Cordero u oveja joven (כֶּשֶׂב), forma metatética de כֶּבֶשׂ, que designa un peq', 'Cordero u oveja joven (כֶּשֶׂב), forma metatética de כֶּבֶשׂ, que designa un pequeño ovino en contextos pastorales y cultuales. En las narrativas de Jacob se refiere al ganado clasificado por sus marcas (Gén 30:32–35, 40). En la legislación sacerdotal es el animal sacrificial por excelencia, especificado para holocaustos (Lev 1:10), ofrendas de paz (Lev 3:7), ofrendas por el pecado (Lev 4:35) y dedicación de primogénitos (Núm 18:17). Deuteronomio 14:4 lo lista entre los animales limpios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107757, 'spa', 'Caldeos (pueblo/nación)', 'Caldeos (pueblo/nación): el pueblo caldeo como grupo étnico-nacional — los habitantes del sur de Mesopotamia, especialmente como agresores y señores imperiales bajo la dinastía neobabilónica. Prominentes en los oráculos proféticos de juicio (Is 13:19, ''la gloria de los caldeos'') y en las narraciones históricas de la destrucción de Jerusalén. Español ''los caldeos'', francés ''les Chaldéens'' y alemán ''der Chaldäer'' lo tratan como un gentilicio estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107761, 'spa', 'Caldea (tierra/región)', 'Caldea (tierra/región): el territorio geográfico de Caldea en el sur de Mesopotamia, usado con fuerza direccional o locativa, a menudo en el sintagma ''tierra de los caldeos'' (éretz kasdim). El español distingue ''Caldea'' (lugar) de ''los caldeos'' (pueblo). Pasajes clave: Jer 50:10 (''Caldea será saqueada''), Ez 16:29 (''la tierra de los caldeos'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107771, 'spa', 'Los caldeos (כַּשְׂדָּי / כַּשְׂדָּאִין, arameo) como nación étnica y como casta', 'Los caldeos (כַּשְׂדָּי / כַּשְׂדָּאִין, arameo) como nación étnica y como casta erudita sacerdotal. Étnicamente, el término identifica al pueblo neobabilónico: Belsasar es ''rey de los caldeos'' (Dan 5:30), y los caldeos destruyeron el templo de Jerusalén (Esd 5:12). Como designación profesional en la corte de Daniel, denota una clase de sabios y adivinos convocados para interpretar sueños y señales reales (Dan 2:5, 10; 4:4; 5:7, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107781, 'spa', 'Tropezar y caer (Nifal)', 'Tropezar y caer (Nifal): tropezar y caer, ser derribado o abatido — enfatizando el resultado consumado del tropiezo más que el traspiés inicial. La fuerza reflexivo-resultativa del Nifal significa ''hallarse caído'', y los contextos tratan abrumadoramente de juicio y derrota: los enemigos caen ante Israel (Sal 9:3), los impíos tropiezan en la oscuridad (Pr 4:19), pero el justo se levanta tras caer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107782, 'spa', 'Tropezar, traspiés, tambalear', 'Tropezar, traspiés, tambalear: Qal — tropezar, dar un traspiés o tambalear, el sentido físico y metafórico básico. Abarca el tropiezo literal (Lv 26:37, tropezando unos con otros en la huida), el fracaso moral (Pr 4:12, el camino del justo donde no se tropieza) y la imaginería poética de debilidad (Job 4:4, fortalecer rodillas vacilantes). El español ''tropezar'' y el alemán ''straucheln'' siguen de cerca al hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107791, 'spa', 'Hacer tropezar (Hifil)', 'Hacer tropezar (Hifil): causativo — hacer que alguien tropiece, hacer caer, provocar la ruina. Carga un peso teológico y moral considerable. En 2 Cr 25:8 Dios mismo tiene poder para ''hacer tropezar''; en 2 Cr 28:23 los dioses de Damasco ''lo hicieron tropezar''; en Sal 64:8 los malvados son hechos tropezar por su propia lengua. El español ''hacer tropezar'' emplea una estructura causativa explícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107792, 'spa', 'Privar de hijos, causar orfandad (Piel ketiv)', 'Privar de hijos, causar orfandad (Piel ketiv): lectura ketiv del Piel en Pr 4:16 y Ez 36:14 — privar de hijos o causar orfandad. Es un sentido textualmente disputado: el texto consonántico ketiv puede leerse como Piel de כָּשַׁל (''privar''), mientras que la tradición qeré enmienda a una forma de שָׁכַל (''quedar sin hijos''). En Ez 36:14 la tierra ''ya no privará de hijos'' a su nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107793, 'spa', 'Ser derribado (ocurrencia aislada)', 'Ser derribado (ocurrencia aislada): una sola aparición en Jer 18:23, donde el profeta ora para que sus perseguidores sean ''derribados'' ante Dios. Se alinea con los sentidos de derrota por tropiezo del Nifal/Hifil (sentidos 2–3), y probablemente representa una variante contextual del tropiezo-derrota más que un significado genuinamente distinto. El contexto imprecatorio del pasaje intensifica la imagen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107797, 'spa', 'Debilitarse, vacilar, fallar', 'Debilitarse, vacilar, fallar: Qal con énfasis en debilitarse, vacilar o fallar en fuerza más que en un tropiezo físico. En Neh 4:10 la fuerza de los cargadores ''ha desfallecido''; en Sal 109:24 las rodillas ''vacilan'' por el ayuno; en Is 35:3 se fortalecen las rodillas débiles. La imagen es de ceder y decaer, no de tropezar con un obstáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107830, 'spa', 'Practicar hechicería', 'Ejercer la hechicería como práctica mágica ilícita. Usado como participio-sustantivo para sus practicantes: la hechicera que no debe vivir (Éx 22:18), los magos egipcios (Éx 7:11), los hechiceros babilónicos (Dn 2:2) y el adivino prohibido (Dt 18:10). Como verbo finito aparece referido a Manasés (2 Cr 33:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107836, 'spa', 'Hechicería, brujería', 'La práctica de la hechicería, siempre en plural keshaphim. Se usa literalmente para las artes mágicas que Dios destruirá —«arrancaré las hechicerías de tu mano» (Mi 5:12) y «a pesar de la multitud de tus hechicerías» (Is 47:9, 12)— y figuradamente como influencia seductora y corruptora, especialmente en las hechicerías de Jezabel (2 R 9:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107841, 'spa', 'Prosperar o convenir', 'Ester 8:5 formula la petición de Ester de manera condicional: «si es recto ante el rey» (וְכָשֵׁר הַדָּבָר לִפְנֵי הַמֶּלֶךְ), empleando el lenguaje de la etiqueta cortesana. Eclesiastés 11:6 expresa incertidumbre agrícola: «no sabes cuál prosperará» (יִכְשָׁר). Eclesiastés 10:10 declara que «la ventaja para hacer prosperar es la sabiduría» (וְיִתְרוֹן הַכְשֵׁיר חָכְמָה).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107842, 'spa', 'Habilidad y provecho', 'Eclesiastés 2:21 lamenta que alguien trabaje «con sabiduría, conocimiento y habilidad» (בְּחָכְמָה וּבְדַעַת וּבְכִשְׁרוֹן) y deba dejarlo a otro. Eclesiastés 4:4 señala que «toda habilidad en el trabajo» (כָּל־כִּשְׁרוֹן הַמַּעֲשֶׂה) nace de la rivalidad entre prójimos. Eclesiastés 5:10 pregunta retóricamente: «¿qué provecho para sus dueños?» (מַה־כִּשְׁרוֹן).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107843, 'spa', 'escrito, registrado (participio)', 'El participio pasivo Qal כָּתוּב/כְּתוּבִים funciona como adjetivo estativo: ''escrito, registrado.'' Se convirtió en la fórmula de citación estándar (''como está escrito en el libro de...'') a lo largo de Reyes, Crónicas y la literatura postexílica (1 R 11:41; 14:19). Esta es la forma más frecuente de la raíz, anclando el concepto de tradición textual con autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107844, 'spa', 'escribir, componer (Qal)', 'Las formas finitas activas del Qal —perfecto, imperfecto, imperativo y waw-consecutivo— denotan el acto concreto de escribir, componer o registrar texto sobre una superficie física. Desde Moisés escribiendo las palabras del Señor (Éx 24:4) hasta Jeremías dictando a Baruc (Jr 36:18), estas formas abarcan mandato divino, correspondencia real y documentación profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107849, 'spa', 'ser escrito (Nifal)', 'El tronco Nifal transmite un pasivo dinámico: ''ser escrito, ser registrado, ser inscrito'' por un agente implícito o no nombrado. A diferencia del participio Qal estativo, el Nifal enfatiza el proceso o decreto de que algo sea escrito. Se concentra notablemente en Ester (1:19; 2:23; 3:9, 12), donde los edictos reales son formalmente promulgados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107871, 'spa', 'escriba, escritor profesional', 'El tronco Piel intensivo y los participios sustantivados designan al escriba profesional o a quien ejerce oficialmente la escritura. Is 10:1 denuncia a quienes ''escriben decretos opresivos'' (מְכַתְּבִים), y Neh 9:38 enumera a ''los que firmaron'' el pacto. El Piel intensifica la actividad hasta convertirla en vocación profesional e institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107878, 'spa', 'don de escritura rechazado', 'En Os 8:12, un texto difícil donde Dios dice ''le escribí,'' las glosas multilingües (esp. para-él) sugieren que el foco recae sobre el destinatario más que sobre el acto de escribir, enfatizando quizá el don personal rechazado de la Torá. El aislamiento del versículo y su sintaxis ambigua han generado interpretaciones variadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107905, 'spa', 'registrar, inscribir en lista', 'Un sentido especializado de escribir como inscribir o registrar nombres en una lista oficial o censo, distinto de la composición literaria. En Sal 87:6, el SEÑOR ''registra'' a los pueblos como nacidos en Sion, y Nm 11:26 menciona a hombres ''inscritos'' entre los ancianos. El desplazamiento semántico de ''componer texto'' a ''inscribir en un padrón'' marca este uso administrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107909, 'spa', 'sistema de escritura', 'En Est 8:9, la frase ''conforme a su escritura'' (כִּכְתָבָם) emplea el derivado nominal de כָּתַב para denotar un sistema de escritura o alfabeto, más que el acto de escribir. El contexto de correspondencia imperial multilingüe confirma este desplazamiento metonímico del verbo al sistema gráfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107918, 'spa', 'Escribir (arameo)', 'Componer, inscribir o registrar por escrito, abarcando tanto la actividad escribal humana como la inscripción sobrenatural. En Esdras, el verbo describe a funcionarios que redactan una carta de acusación (Esd 4:8, 3mp perfecto), a los ancianos judíos que registran nombres para el rey (Esd 5:10, 1cp imperfecto nikhtub) y la anotación archivística ''así estaba escrito en ella'' (Esd 5:7; 6:2, pasivo peʿil). En Daniel 5:5, describe los dedos divinos que escriben en la pared del palacio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107924, 'spa', 'Escritura o sistema de escritura', 'Escritura o sistema de escritura. Un sistema de escritura o conjunto de caracteres usados por un pueblo o lengua determinados. Las apariciones se concentran en los libros del período persa, donde el imperio multilingüe exigía atención a la diversidad ortográfica: ''la escritura del documento estaba escrita en arameo'' (Esd 4:7), y la fórmula repetida ''conforme a la escritura de cada provincia y la lengua de cada pueblo'' (Est 1:22; 3:12; 8:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107925, 'spa', 'Documento escrito o carta', 'Documento escrito o carta. Un documento escrito, carta, decreto o inscripción, cualquier texto compuesto considerado como un artefacto escrito concreto. Las apariciones abarcan el plan escrito de David para el Templo (''todo esto por escrito de la mano de Jehová'', 1 Cr 28:19), la carta de Hiram a Salomón (2 Cr 2:11) y los edictos reales de Ester (Est 3:14; 4:8; 8:8). El español ''escrito'' capta bien el sentido genérico de ''una pieza de escritura''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107926, 'spa', 'Registro o archivo', 'Registro o archivo. Un registro, acta de inscripción o lista genealógica oficial. Las apariciones señalan la función administrativa de los registros escritos como instrumentos de pertenencia social: los exiliados que regresaron y no pudieron encontrar ''su registro'' de linaje sacerdotal fueron excluidos del servicio sagrado (Esd 2:62; Neh 7:64), y Ezequiel advierte que los falsos profetas no estarán ''en el registro de la casa de Israel'' (Ez 13:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107936, 'spa', 'Escritura, documento', 'Un texto escrito, inscripcion o documento oficial que abarca decretos reales, inscripciones divinas misteriosas y escritura autoritativa. El termino domina la narrativa de Belsasar: el rey ve ''la escritura'' en la pared y convoca a interpretes (Dn 5:7-8, 15-17, 24-25). Daniel 10:21 lo eleva a un registro celestial con ''la escritura de verdad'', un libro divino de eventos futuros. Esdras 6:18 lo aplica a la Escritura mosaica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107941, 'spa', 'Quitim (nombre propio)', 'Sustantivo gentilicio que originalmente designaba a los habitantes de Kition en Chipre, derivado del fenicio kt. Aparece como descendiente de Javan (Gn 10:4 = 1 Cr 1:7), vinculandolo al mundo griego/egeo. Isaias habla de ''la tierra de Quitim'' refiriendose a Chipre (Is 23:1, 12). El uso profetico amplia el referente: las ''islas de los Quitim'' de Jeremias (2:10) y la mencion de Ezequiel (27:6) abarcan costas mediterraneas. En Daniel 11:30, ''naves de Quitim'' designa la flota romana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107947, 'spa', 'Machacado, majado', 'Machacado o majado, describiendo el aceite de oliva de la mas alta calidad obtenido al triturar aceitunas en un mortero en vez de prensarlas mecanicamente. El termino aparece solo en la frase constructa שֶׁמֶן כָּתִית (''aceite machacado''). En Ex 27:20 y Lv 24:2 especifica el aceite puro machacado necesario para mantener encendida la lampara del tabernaculo; en Ex 29:40 y Nm 28:5 acompana las ofrendas de cereal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107952, 'spa', 'Oro fino, oro puro', 'Término poético y elevado para designar oro fino o puro, empleado para denotar oro de la más alta calidad. El hebreo porta un peso literario ausente del común zahav. Aparece frecuentemente en constructo con Ofir (Is 13:12; Job 28:16; Sal 45:9) o junto a paz, ''oro refinado'' (Cnt 5:11), estableciéndolo como superlativo. Proverbios 25:12 lo empareja con joyas de oro como imagen de sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107960, 'spa', 'La prenda interior principal del vestuario israelita antiguo, una túnica de larg', 'La prenda interior principal del vestuario israelita antiguo, una túnica de largo corporal usada junto a la piel. Abarca las túnicas de piel que Dios hizo para Adán y Eva (Gn 3:21), la célebre כְּתֹנֶת פַּסִּים de José que provocó los celos de sus hermanos (Gn 37:3, 23, 31), la vestidura interior de lino prescrita para Aarón y sus hijos (Éx 28:39-40; Lv 8:7, 13), y la túnica de princesa que Tamar rasgó en su aflicción (2 Sam 13:18-19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107978, 'spa', 'Lado, ladera, flanco', 'Lado, ladera, flanco: el costado, la ladera o el flanco de un accidente geográfico, ciudad o estructura. La metáfora corporal se proyecta sobre el terreno: el ''hombro'' de una colina es su ladera, y el ''hombro'' de una puerta o muro es su cara lateral. El español ''ladera'' y el francés ''pente'' captan el sentido topográfico. Este sentido predomina en las listas de límites de Josué (Jos 15:8–11; 18:12–19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107979, 'spa', 'Hombro (parte del cuerpo)', 'Hombro (parte del cuerpo): el hombro físico de una persona o animal, la parte del cuerpo entre el cuello y el brazo superior usada para cargar pesos. Goliat lleva una jabalina de bronce entre sus hombros (1 S 17:6), los levitas portan el arca sobre sus hombros (1 Cr 15:15), y Dios habita ''entre los hombros'' de Benjamín (Dt 33:12). Zacarías 7:11 emplea la vívida imagen del hombro terco que se aparta de la instrucción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (107980, 'spa', 'Hombrera, tirante de soporte', 'Hombrera, tirante de soporte: las hombreras o tirantes de soporte del efod sacerdotal, un término técnico de confección de vestiduras. Estos componentes estructurales descansan sobre los hombros del sumo sacerdote y unen los paneles delantero y trasero del efod, portando las piedras de ónice memoriales grabadas con los nombres de las doce tribus de Israel (Éx 28:7, 12, 25, 27; 39:4, 7, 18, 20). El español ''hombreras'' capta con precisión este sentido técnico textil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108010, 'spa', 'Rodear, cercar', 'Rodear o cercar, ya sea en un asedio hostil o en un envolvimiento metafórico (Jue 20:43; Sal 22:12; Sal 142:7; Hab 1:4). El español rodearon y «me han cercado» confirman el sentido espacial de cerrar el paso. En Salmo 22:12, la imagen de los toros rodeando al sufriente tiene profunda resonancia mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108013, 'spa', 'Coronar, adornar', 'Coronar o adornar, extensión figurativa del Hifil donde el cerco se transforma en honor. Proverbios 14:18 declara que los prudentes «se coronan de conocimiento». La conexión denominativa con keter («corona»), usada para coronas reales en Ester, muestra cómo rodear puede significar tanto amenaza como honra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108014, 'spa', 'Esperar, ser paciente', 'Esperar o ser paciente, sentido de influencia aramea que se encuentra únicamente en Job 36:2, donde Elihú insta: «Espérame un poco». El siríaco y arameo kattar (Pael = esperar, permanecer, soportar) proporcionan la evidencia cognada. Los discursos de Elihú son ampliamente reconocidos por sus arameísmos, y este uso es un ejemplo notable de préstamo interlingüístico dentro de la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108016, 'spa', 'Corona real persa', 'Ester 1:11 registra la orden de Asuero de que Vasti se presente «con la corona real» (בְּכֶתֶר מַלְכוּת). Al convertirse Ester en reina, el rey «puso la corona real sobre su cabeza» (2:17). El honor imaginado por Amán incluye llevar «una corona real» (6:8). La frase כֶּתֶר מַלְכוּת, siempre en estado constructo, designa específicamente la corona de soberanía persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108017, 'spa', 'El capitel ornamental o corona en la parte superior de una columna, usado exclus', 'El capitel ornamental o corona en la parte superior de una columna, usado exclusivamente en descripciones arquitectónicas del templo de Salomón y su destrucción. Todas las apariciones se refieren a los elaborados capiteles de bronce sobre los pilares Jaquín y Boaz (1 Re 7:16-42), con descripciones paralelas en la narrativa de la destrucción (2 Re 25:17; Jer 52:22). Estos capiteles de cinco codos de alto presentaban intrincada obra de celosía, hileras de granadas y diseños en forma de lirio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108028, 'spa', 'Machacar o pulverizar', 'Machacar o pulverizar. El sentido activo de machacar o pulverizar algo en pedazos pequeños mediante golpes repetidos. Moisés molió el becerro de oro hasta reducirlo a polvo fino (Dt 9:21); Ezequías destrozó la serpiente de bronce (2 R 18:4). En el Salmo 89:23, Dios promete aplastar a los enemigos del salmista. El Piel intensifica la minuciosidad de la destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108029, 'spa', 'Ser machacado o destrozado', 'Ser machacado o destrozado. El sentido pasivo o estativo: ser machacado, destrozado o quebrantado. En Levítico 22:24, un animal con testículos machacados no es apto para el sacrificio. Isaías 30:14 compara el juicio con una vasija de alfarero tan completamente destrozada que ningún fragmento queda útil. Isaías 24:12 y 2 Crónicas 15:6 extienden esto a ciudades y naciones reducidas a ruinas. El Hofal refuerza la pasividad del sujeto ante la fuerza destructora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108032, 'spa', 'Derrotar militarmente', 'Derrotar militarmente. Un sentido militar: derribar o aplastar a una fuerza enemiga en batalla. En Números 14:45, los amalecitas y cananeos derrotaron el avance no autorizado de Israel; en Deuteronomio 1:44, los amorreos los abatieron. El Hifil causativo enfatiza que una parte inflige una derrota aplastante sobre la otra: los golpes son dirigidos, estratégicos y decisivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108033, 'spa', 'Forjar, dar forma a golpes', 'Forjar, dar forma a golpes. Golpear metal para darle una nueva forma: forjar en vez de destruir. Isaías 2:4 y Miqueas 4:3 vislumbran naciones que forjan espadas en rejas de arado, mientras Joel 3:10 invierte la imagen: rejas de arado en espadas. La misma acción violenta que destruye en otros contextos aquí transforma y reutiliza. ''Forjarán'' en español revela esta dimensión constructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108045, 'spa', 'negación simple (no)', 'Partícula negativa estándar para negar verbos, adjetivos y cláusulas: la simple aserción de que algo no es el caso. Comprende la inmensa mayoría de las ocurrencias (4.839), desde ''aún no había llovido'' (Gn 2:5) hasta ''no tuvo en cuenta'' (Gn 4:5). Equivale al ''no'' español en su función proposicional básica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108048, 'spa', 'negación interrogativa retórica', 'Negación interrogativa retórica, típicamente como הֲלֹא, que espera respuesta afirmativa: ''¿Acaso no...?'' Con 275 ocurrencias, es un recurso persuasivo fundamental del discurso hebreo. ''¿No saqué yo a Israel de Egipto?'' (Am 9:7) exige asentimiento. La negación paradójicamente afirma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108050, 'spa', 'sin (privativo)', 'Sentido privativo: ''sin, carente de'', formado con preposiciones בְּלֹא o לְלֹא. Números 35:22-23 emplea esta construcción para matar ''sin enemistad'' y ''sin ver''. La partícula negativa se combina con preposiciones para crear una categoría gramatical distinta que expresa ausencia o privación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108052, 'spa', '¡no! (rechazo independiente)', '''¡No!'' como enunciado completo de rechazo o negación. Sara dice ''¡No!'' al ser descubierta riendo (Gn 18:15), los ángeles rechazan la hospitalidad de Lot con ''¡No!'' (Gn 19:2), y los hermanos de José protestan ''No, señor mío'' (Gn 42:10). Funciona como negativa exclamativa independiente, distinta del papel sintáctico a nivel de cláusula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108067, 'spa', 'ni (negación en serie)', 'Negación conjuntiva en serie: ''ni, y tampoco'', enlazando elementos negados adicionales en una cadena. En Sal 115:17, ''los muertos no alaban al Señor, ni cuantos descienden al silencio'', la combinación waw + לֹא extiende una negación previa, coordinando negaciones sucesivas en una serie negativa acumulativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108068, 'spa', 'No (partícula negativa aramea)', 'No (partícula negativa aramea): la partícula negativa estándar aramea ''no'', usada para negar verbos, participios, adjetivos y cláusulas tanto en oraciones declarativas como interrogativas. Funcionalmente equivalente al hebreo לֹא y traducida de manera uniforme en todos los idiomas — español ''no'', francés ''ne...pas'', alemán ''nicht''. Omnipresente en las secciones arameas de Esdras (4:13–16) y Daniel (2:5–10), cubriendo 81 de 82 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108071, 'spa', 'Como nada, sin valor (negación comparativa)', 'Como nada, sin valor (negación comparativa): un uso sustantivado o comparativo en la construcción כְּלָה (''como nada, como insignificancia''), donde la partícula negativa adquiere una función cuasi-nominal que denota inexistencia o total insignificancia. El español ''como nada'' hace explícita la comparación. Atestiguado únicamente en Dn 4:35, donde todos los habitantes de la tierra son considerados ''como nada'' ante la soberanía de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108072, 'spa', 'Ciudad en Galaad', '2 Samuel 9:4-5 ubica a Mefiboset «en casa de Maquir hijo de Amiel, en Lo-debar» (בְּלוֹ דְבָר), donde David lo busca para honrar su pacto con Jonatán. 2 Samuel 17:27 nombra a Maquir «de Lo-debar» entre quienes abastecieron a las fuerzas de David durante la revuelta de Absalón. La ubicación exacta del asentamiento sigue siendo incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108073, 'spa', 'Estar cansado, fatigarse', 'Estar cansado, fatigarse. Qal y Nifal intransitivo: volverse cansado, agotado o fatigado, ya sea por esfuerzo físico o por tensión emocional. Los sodomitas ''se cansaron'' buscando a tientas la puerta (Gn 19:11); Egipto estaba ''agotado'' de su propia agua contaminada (Éx 7:18). En los Salmos y los profetas, el cansancio se vuelve espiritual: Dios está ''cansado'' de soportar el culto hueco de Israel (Is 1:14), y el perezoso está ''demasiado cansado'' para traer su mano a la boca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108074, 'spa', 'Cansar, agotar a otro', 'Cansar, agotar a otro. Hifil causativo: causar cansancio, fatigar o agotar a alguien. Este sentido aparece en algunas de las confrontaciones más incisivas de la Escritura. En Miqueas 6:3, Dios pregunta a Israel: ''¿En qué te he cansado?'', un llamado que presupone la acusación. Isaías 7:13 presenta una aguda escalada: ''¿No os basta cansar a los hombres, que también cansáis a mi Dios?'' Job 16:7 lamenta que Dios ''me ha agotado'' mediante el sufrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108090, 'spa', 'Lea (nombre propio', 'Lea (nombre propio: primera esposa de Jacob): nombre propio de la hija mayor de Labán y primera esposa del patriarca Jacob. Madre de Rubén, Simeón, Leví, Judá, Isacar, Zabulón y Dina (Gn 29:32-35; 30:17-21; 35:23). Su narrativa abarca Génesis 29-35 y 46:15-18, y fue sepultada en Macpela (Gn 49:31). Rut 4:11 la conmemora como matriarca que edificó la casa de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108099, 'spa', 'pueblo, nación', 'pueblo, nación: un pueblo o nación como comunidad étnica — el sentido léxico principal que cubre prácticamente todas las ocurrencias. Se usa en singular para Israel (Is 51:4, «mi nación») o para pueblos individuales como Edom (Gn 25:23), y en plural para las naciones en general (Sal 2:1, «¿Por qué se amotinan los pueblos?»; Is 34:1). Término de registro poético elevado, propio de profecía, salmos y bendiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108109, 'spa', 'entre (los pueblos)', 'entre (los pueblos): un uso cuasi-adverbial dentro de una frase preposicional que significa «entre los pueblos» (Sal 44:14), donde la palabra funciona menos como sustantivo independiente y más como parte de una expresión locativa. El sentido subyacente de «pueblos» permanece, aunque las traducciones lo reducen a una partícula relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108129, 'spa', 'corazón, ser interior', 'La persona interior como centro del pensamiento, la volición, la emoción y el discernimiento moral: el sentido bíblico-antropológico dominante que cubre casi las 572 ocurrencias. En Éx 35:21 el corazón ''impulsa'' a alguien a dar; en Pr 23:15 un hijo sabio alegra el corazón de su padre. Todas las lenguas principales lo traducen con un solo vocablo nuclear (español ''corazón,'' francés ''coeur,'' alemán ''Herz'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108137, 'spa', 'centro, medio (espacial)', 'Extensión espacial o locativa: el interior físico, centro o medio de una entidad no personal. Se encuentra en expresiones como ''en el corazón del mar'' (Éx 15:8), ''en el corazón de la encina'' (2 S 18:14) y ''en el corazón de los cielos'' (Dt 4:11). Las glosas multilingües emplean consistentemente frases preposicionales, revelando que los traductores reconocen esta acepción locativa como distinta de la antropológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108194, 'spa', 'nota textual problemática', 'Una ocurrencia textual problemática en 1 S 25:3, donde la lectura del texto masorético parece involucrar una corrupción textual o nota de escriba. Las glosas multilingües lo traducen como una etiqueta gentilicia entre corchetes ''[Calebita],'' sugiriendo que la palabra aquí no funciona como ''corazón'' sino que puede ser una mala vocalización o anotación marginal relacionada con la identidad del clan de Caleb.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108207, 'spa', 'Corazón e intelecto', 'Job 11:12 plantea una pregunta retórica en Niphal imperfecto: ''¿adquirirá entendimiento el hombre hueco?'' (וְאִישׁ נָבוּב יִלָּבֵב), sugiriendo una imposibilidad intelectual. Cantares 4:9 repite dos veces ''me has robado el corazón'' (לִבַּבְתִּנִי) para enfatizar el arrebato amoroso. Algunos interpretan este Piel como ''animar'' o ''dar ánimo'', aunque predomina el sentido de cautivar afectivamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108209, 'spa', 'corazón, ser interior', 'La persona interior como sede del pensamiento, el entendimiento, la voluntad, la emoción y el carácter moral: 250 de 252 ocurrencias de forma abrumadora. Este es el לֵבָב del Shemá (Dt 6:5), de la petición de Salomón por un ''לֵבָב perspicaz'' (1 R 3:9) y de la promesa del nuevo pacto de que Dios escribirá su ley en el לֵבָב (Jr 31:33). Todas las lenguas principales deben elegir una sola metáfora orgánica para cubrir este vasto campo interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108255, 'spa', 'centro, profundidad (espacial)', 'El centro físico o interior de algo, usado espacialmente: una única ocurrencia poética en Jon 2:3, donde el profeta que se ahoga clama desde ''el לֵבָב de los mares.'' Aquí la palabra funciona como metáfora espacial para la profundidad más íntima, el mismísimo núcleo del océano. El español ''en corazón de'' y el alemán ''in-Herz'' preservan la extensión metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108261, 'spa', 'devoción íntegra', 'Devoción o integridad de corazón entero: una única ocurrencia en 1 Cr 12:39, donde los guerreros vienen con un לֵבָב ''completo/entero'' para hacer rey a David. El sentido es adverbial o cualitativo, describiendo la manera del compromiso más que el órgano en sí. El español ''íntegro'' capta esta dimensión cualitativa que se sitúa en el límite entre el sentido nuclear y un matiz adverbial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108268, 'spa', 'Corazón, mente, ser interior', 'El ser interior entendido como sede del pensamiento, la voluntad y la emoción, equivalente arameo del hebreo לֵב/לֵבָב. En los capítulos arameos de Daniel describe la mente de Nabucodonosor cambiada por la de un animal (Dan 4:16), su corazón enaltecido por la arrogancia (Dan 5:20-21), el acceso de Daniel a los pensamientos secretos del rey (Dan 2:30) y una bestia que recibe entendimiento humano (Dan 7:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108272, 'spa', 'Corazón (forma plural/femenina)', 'La persona interior, que abarca el carácter moral, la intención y el pensamiento — variante femenina/plural de leb empleada en contextos de escrutinio divino y evaluación moral. Dios prueba los corazones como el refinador prueba el metal (Prov 17:3; 21:2), los escudriña más profundamente que al Seol mismo (Prov 15:11) y juzga su rectitud (Sal 7:9; 125:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108278, 'spa', 'Incienso (resina aromática para sahumerio)', 'Incienso (resina aromática para sahumerio). La resina blanca y fragante de los árboles de Boswellia, parte integral de la práctica cultual israelita. Prescrita como uno de los cuatro ingredientes del incienso sagrado (Éx 30:34), se colocaba sobre las ofrendas de grano (Lv 2:1, 15) y junto al pan de la proposición (Lv 24:7). Las traducciones convergen entre lenguas: incienso (español), encens (francés), Weihrauch (alemán), لُبان (árabe), todas apuntando a la misma sustancia aromática. También aparece en la imaginería poética del Cantar de los Cantares (4:6) y en la crítica profética del ritualismo vacío (Jer 6:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108285, 'spa', 'vestido, ropa', 'vestido, ropa: una prenda o artículo de vestir llevado sobre el cuerpo, que abarca la ropa cotidiana, el atuendo ceremonial y las vestiduras figuradas de honor o vergüenza. Los pasajes clave van desde la bendición de Jacob describiendo vestidos lavados en vino (Gn 49:11) hasta el lamento de Job de que Dios lo agarra por la vestidura (Job 30:18), y la mujer virtuosa vestida de fuerza y dignidad (Pr 31:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108294, 'spa', 'vestido de, revestido', 'vestido de, revestido: un uso participial o estativo que significa «vestido de, revestido de», funcionando como predicado que describe el estado de vestimenta de alguien en vez de nombrar la prenda en sí. Atestiguado en Ezequiel 9:11, donde el varón «vestido de lino» regresa con su informe. Distingue la función adjetival del sentido sustantivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108307, 'spa', 'Derribamiento y ruina', 'Proverbios 10:8, 10 advierten que ''el necio de labios será derribado'' (אֱוִיל שְׂפָתַיִם יִלָּבֵט), con fraseología idéntica que subraya la consecuencia inevitable de la necedad verbal. Oseas 4:14 declara juicio: ''el pueblo sin entendimiento será destruido'' (עָם לֹא־יָבִין יִלָּבֵט), enlazando la ceguera moral con la ruina nacional. El Niphal indica recepción pasiva del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108310, 'spa', 'Leona (leon hembra)', 'Leona o gran leon — termino poetico y arcaico usado en bendiciones tribales, oraculos profeticos y poesia sapiencial para evocar poder feroz, majestad o pavor. La bendicion de Jacob sobre Juda (Gn 49:9), los oraculos de Balaam sobre Israel (Nm 23:24; 24:9), la bendicion de Moises sobre Dan o Gad (Dt 33:20) y la imagineria profetica de juicio (Is 5:29; 30:6; Os 13:8; Jl 1:6; Nah 2:12) emplean esta palabra.');